// CategoryDeleteOne builds the delete of one `categories` row. Start one with
// `Graph.categories().delete_one(node)` or `delete_one_id(id)`.
pub struct CategoryDeleteOne {
	graph Graph
pub:
	data vgraph.MutationData
}

// delete_one starts the delete of the row of `node`.
pub fn (q CategoryQuery) delete_one(node CategoryNode) CategoryDeleteOne {
	return q.delete_one_id(node.category.id)
}

// delete_one_id starts the delete of the row with the key `id`.
pub fn (q CategoryQuery) delete_one_id(id int) CategoryDeleteOne {
	return CategoryDeleteOne{
		graph: q.graph
		data:  vgraph.MutationData{
			op:      .delete_one
			table:   'categories'
			row_key: id.str()
		}
	}
}

// exec deletes the row, with its join table rows, in one transaction, or
// returns a `NotFoundError`.
pub fn (b CategoryDeleteOne) exec() ! {
	if !b.graph.client.delete_one(b.data)! {
		return NotFoundError{
			table: 'categories'
		}
	}
}

